// Phan tich va phan loai muc do nghiem trong cua cac task bi stuck
const stuckTasks = $input.all().map(item => {
  const d = item.json;
  const inactiveHours = parseFloat(d.inactive_hours) || 0;

  // Phan loai muc do nghiem trong
  let severity = 'MEDIUM';
  if (inactiveHours >= 72 || d.priority === 'URGENT') {
    severity = 'CRITICAL';
  } else if (inactiveHours >= 48 || d.priority === 'HIGH') {
    severity = 'HIGH';
  }

  // Kiem tra co qua han (overdue) khong
  const isOverdue = d.due_date ? new Date(d.due_date) < new Date() : false;
  if (isOverdue) {
    severity = 'CRITICAL';
  }

  return {
    task_id: d.task_id,
    task_title: d.task_title,
    status: d.status,
    priority: d.priority,
    story_points: d.story_points,
    project_id: d.project_id,
    project_name: d.project_name,
    assignee_id: d.assignee_id,
    assignee_name: d.assignee_name || 'Chua gan',
    assignee_email: d.assignee_email,
    inactive_hours: inactiveHours,
    due_date: d.due_date,
    is_overdue: isOverdue,
    severity: severity,
    alert_message: `[${severity}] Task "${d.task_title}" bi stuck o trang thai ${d.status} da ${Math.round(inactiveHours)} gio` + (isOverdue ? ' (DA QUA HAN!)' : '')
  };
});

// Sap xep theo muc do: CRITICAL > HIGH > MEDIUM
const severityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2 };
stuckTasks.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

// Thong ke tong hop
const summary = {
  total_stuck: stuckTasks.length,
  critical_count: stuckTasks.filter(t => t.severity === 'CRITICAL').length,
  high_count: stuckTasks.filter(t => t.severity === 'HIGH').length,
  medium_count: stuckTasks.filter(t => t.severity === 'MEDIUM').length,
  overdue_count: stuckTasks.filter(t => t.is_overdue).length,
  scanned_at: new Date().toISOString()
};

return [{
  json: {
    summary: summary,
    stuck_tasks: stuckTasks
  }
}];

